    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const sections = document.querySelectorAll('div[id]');
            const navLinks = document.querySelectorAll('aside nav a');

            const observerOptions = {
                root: null,
                rootMargin: '-20% 0px -70% 0px',
                threshold: 0
            };

            const observer = new IntersectionObserver((entries) => {
                entries.forEach(entry => {
                    if (entry.isIntersecting) {
                        navLinks.forEach(link => {
                            link.classList.remove('text-primary');
                            link.querySelector('span:last-child').classList.remove('text-primary');
                            if (link.getAttribute('href').substring(1) === entry.target.id) {
                                link.querySelector('span:last-child').classList.add('text-primary');
                            }
                        });
                    }
                });
            }, observerOptions);

            sections.forEach(section => observer.observe(section));

            // Smooth scroll
            navLinks.forEach(link => {
                link.addEventListener('click', (e) => {
                    e.preventDefault();
                    const targetId = link.getAttribute('href');
                    const targetElement = document.querySelector(targetId);
                    window.scrollTo({
                        top: targetElement.offsetTop - 100,
                        behavior: 'smooth'
                    });
                });
            });
        });
    </script></main><footer class="w-full bg-surface-container-lowest py-section-gap border-t border-outline-variant/10"><div class="max-w-container-max mx-auto px-margin-mobile lg:px-margin-desktop"><div class="flex flex-col md:flex-row justify-between items-center gap-unit"><div class="flex items-center gap-4 opacity-70"><img alt="Blinglink" class="h-6 w-auto grayscale brightness-200" src="https://lh3.googleusercontent.com/aida/AP1WRLvFx9epfW5F0ifQUgFkzC8oaW_8wRR9BPI9YcoRDx_NtaVCl6h4EUj8uQ0N0-CUKXHpyXxE4UZR7eMK5XEgNV0Y0JpO2DxLCAysgJb_3Au-G26dWr7wbrFFPNZBV2LDCDsykoaj6AIuZm4AXdOyG0wgDTzKDFd60da0F7RnoF3FP1EMKugf-S_lgE_NEaeQEyjVzQCNfZm9VIIK3F8OCZbUIT06In5-j-IMF8WMpmOkBe6hs0K38zi1m94"/></div><p class="font-label-sm text-label-sm text-on-surface-variant tracking-widest uppercase">© 2026 Blinglink. Exquisite Connection.</p></div></div></footer></body></html>
